function chats(query=''){state.app='whatsapp';state.tab='Chats';const list=[{name:'Family Business',time:'9:08 PM',preview:'Kris: Love you girls!!! ❤️',badge:23},...['Kris','Kim','Kylie','Khloé','Kendall','Kourtney'].map((n,i)=>({name:n,time:['9:04 PM','Wednesday','Wednesday','Today','Today','Wednesday'][i],preview:privateChats[n].at(-1).text,badge:n==='Kris'?2:0}))].filter(c=>(state.filter==='Unread'?c.badge:state.filter==='Groups'?c.name==='Family Business':true)&&(!query||c.name.toLowerCase().includes(query.toLowerCase())||c.preview.toLowerCase().includes(query.toLowerCase())));display(`<section class="app"><div class="wa-top"><div class="wa-topline"><button aria-label="More chat options" data-action="wa-menu">${icon('ellipsis')}</button><div class="pair"><button aria-label="Camera" data-open="camera">${icon('camera')}</button><button aria-label="New chat" data-open="phone">${icon('plus')}</button></div></div><h1>Chats</h1><label class="search-field">${icon('search')}<input id="chat-search" placeholder="Search" value="${esc(query)}" aria-label="Search chats"></label><div class="filters">${['All','Unread','Groups'].map(f=>`<button data-filter="${f}" class="${state.filter===f?'selected':''}">${f}</button>`).join('')}</div></div><div class="scroll"><div class="archive-row">${icon('archive')} Archived</div><div class="chat-list">${list.length?list.map(c=>`<button class="chat-row ${c.badge?'unread':''}" data-chat="${c.name}">${avatar(c.name)}<div class="rowtext"><div class="rowhead"><span>${c.name}</span><time>${c.time}</time></div><p>${esc(c.preview)}</p></div>${c.badge?`<i class="rowbadge">${c.badge}</i>`:''}</button>`).join(''):'<p class="no-result">No chats found</p>'}</div></div>${tabs('Chats')}</section>`,true);}
function msg(m,time='9:42 AM',prev='',idx=0){if(m.sender==='system')return `<div class="wa-system">${esc(m.text)}</div>`;if(m.sender==='invite')return `<div class="wa-message attachment first"><div class="wa-sender" style="color:#a76518">Kris</div><button data-action="invite-photo" aria-label="Open brand preview invitation">${invite()}</button><span class="wa-meta">12:26 PM</span><div style="clear:both"></div></div>`;const sent=m.sender==='Mia';return `<div class="wa-message ${sent?'sent':''} ${prev!==m.sender?'first':''}" data-message-index="${idx}">${!sent&&prev!==m.sender?`<div class="wa-sender" style="color:${colors[m.sender]||'#4269ad'}">${esc(m.sender)}</div>`:''}<span class="wa-text">${esc(m.text)}</span><span class="wa-meta"><time>${time}</time>${sent?'<span class="ticks">✓✓</span>':''}</span><div style="clear:both"></div></div>`;}
function groupChat(chapter=null,replay=false){clearTimers();state.app='chat';state.chat='Family Business';if(chapter!==null)state.chapter=chapter;const start=state.chapter;let messages='<div class="encrypted">🔒 Messages and calls are end-to-end encrypted. Only people in this chat can read, listen to, or share them.</div><div class="wa-system">Kris created group “Family Business”</div>';let prev='';for(let i=0;i<STORY.scenes.length;i++){const s=STORY.scenes[i];messages+=`<div class="chat-date" id="chapter-${i}">${s.time.split(' · ')[0]==='Friday'?'Friday, October 16':'Wednesday, October 14'} · ${s.time.split(' · ')[1]}</div>`;prev='';s.messages.forEach((m,j)=>{messages+=msg(m,s.time.split(' · ')[1],prev,j);prev=m.sender;});}messages+=(state.drafts['Family Business']||[]).map(m=>msg(m,m.time,'Mia')).join('');display(`<section class="app"><header class="wa-header"><button class="back" data-action="chats" aria-label="Back to chats">${icon('back')}</button><button class="group-info" data-action="group-info">${avatar('Family Business','tiny')}<span><strong>Family Business</strong><small>Kris, Kim, Kourtney, Khloé, Kendall, Kylie, You</small></span></button><div class="tools"><button data-action="video-call" aria-label="Video call">${icon('video')}</button><button data-action="chat-menu" aria-label="Group menu">${icon('ellipsis')}</button></div></header><div class="chat-body" id="chat-body">${messages}</div><div class="jump-bar" aria-label="Jump to scene">${STORY.scenes.map((s,i)=>`<button data-jump="${i}" class="${i===start?'active':''}">${['The idea','The calls','Kourtney leaves','The invite','The rescue','Friday AM','After the preview'][i]}</button>`).join('')}</div><div class="fiction-tag">FICTIONAL FAN STORY · ALL MESSAGES INVENTED</div>${composer()}</section>`,true);jump(start);}
function jump(i){state.chapter=i;$$('[data-jump]').forEach(b=>b.classList.toggle('active',+b.dataset.jump===i));const el=$('#chapter-'+i),box=$('#chat-body');if(el&&box)box.scrollTop=el.offsetTop-10;const s=STORY.scenes[i];$('#time').textContent='9:08';}
function composer(){return `<form class="composer" id="message-form"><button type="button" data-action="attach" aria-label="Attach a file">${icon('plus')}</button><label class="entry"><input id="message-input" aria-label="Type a fictional message" autocomplete="off"><button type="button" data-action="emoji" aria-label="Add emoji">${icon('sticker')}</button></label><button type="submit" aria-label="Send local message">${icon('send')}</button><button type="button" data-action="voice-note" aria-label="Voice note">${icon('mic')}</button></form>`;}
function privateChat(name){clearTimers();state.app='private';state.chat=name;let prev='';const rows=[...privateChats[name],...(state.drafts[name]||[])];display(`<section class="app"><header class="wa-header"><button class="back" data-action="chats" aria-label="Back to chats">${icon('back')}</button><button class="group-info" data-action="contact-info">${avatar(name,'tiny')}<span><strong>${esc(name)}</strong><small>tap here for contact info</small></span></button><div class="tools"><button data-call="${name}" aria-label="Call ${name}">${icon('video')}</button><button data-call="${name}" aria-label="Call ${name}">${icon('phone')}</button></div></header><div class="chat-body" id="chat-body"><div class="chat-date">Wednesday, October 14</div><div class="encrypted">🔒 Messages and calls are end-to-end encrypted.</div>${rows.map((m,i)=>{let s=msg(m,m.time||'8:31 PM',prev,i);prev=m.sender;return s}).join('')}</div><div class="fiction-tag">FICTIONAL BONUS CHAT · NOT REAL PRIVATE MESSAGES</div>${composer()}</section>`,true);}
function groupInfo(){state.app='groupinfo';display(`<section class="app group-profile"><div class="toolbar"><button data-action="back-group">${icon('back')} Back</button><h2>Group info</h2><button data-action="chat-menu">${icon('ellipsis')}</button></div><div class="scroll"><div style="padding-top:24px">${avatar('Family Business','big')}<h2>Family Business</h2><p class="sub">Group · 7 members</p></div><div class="panel"><div class="row"><span>A very normal family group chat.<small>Created by Kris · October 14</small></span></div><div class="row"><span>Media, links, and docs</span><button class="right" data-open="photos">12 ›</button></div><div class="row"><span>Mute notifications</span><button class="toggle ${state.muted?'':'off'}" data-action="mute" aria-label="Toggle group mute"></button></div></div><div class="panel"><div class="section-label">7 MEMBERS</div>${names.map(n=>`<button class="row" ${n==='Mia'?'data-action="about"':`data-chat="${n}"`} style="width:100%;text-align:left">${avatar(n,'tiny')}<span>${n==='Mia'?'You':n}<small>${n==='Kris'?'Love you girls!!! ❤️':n==='Kourtney'?'Notifications off.':n==='Mia'?'Mia · fictional younger relative':''}</small></span>${n==='Kris'?'<span class="right">Group admin</span>':''}</button>`).join('')}</div><p class="notifications-note">Fictional story. Mia is Kris’s younger relative,<br>not her daughter. All conversations are invented.</p></div></section>`,true);}
function waTab(tab){if(tab==='Chats')return chats();state.app='whatsapp';state.tab=tab;if(tab==='Calls')return contacts('Calls');if(tab==='Updates'){display(`<section class="app"><div class="toolbar"><h2>Updates</h2><button data-open="instagram">${icon('camera')}</button></div><div class="scroll content-page"><h2 style="font-size:30px">Status</h2><p style="font-size:11px;color:#888">Recent updates</p>${['Kylie','Kendall','Khloé'].map((n,i)=>`<button class="chat-row" data-story="${i}" style="padding:13px 0">${avatar(n)}<div class="rowtext"><b>${n}</b><p>Friday · ${i+1}h ago</p></div></button>`).join('')}</div>${tabs('Updates')}</section>`,true);}else if(tab==='Communities'){display(`<section class="app"><div class="toolbar"><h2>Communities</h2></div><div class="scroll"><div class="content-page"><h2>Family, first.</h2><p style="color:#888;font-size:13px;line-height:1.5">One family. Several businesses. Too many opinions.</p></div><button class="chat-row" data-chat="Family Business">${avatar('Family Business')}<div class="rowtext"><b>Family Business</b><p>7 members · 23 unread</p></div></button></div>${tabs('Communities')}</section>`,true);}else settings(true);}
const photoItems=[{type:'image',src:'media/wardrobe.jpg',title:'Saved to “Brand ideas”',caption:'Reference image · Saved from the web, not an original design.'},{type:'invite',title:'MIA — A first look',caption:'Invitation created by Kris. Fictional event prop.'},{type:'image',src:'media/studio.jpg',title:'Location inspiration',caption:'Reference image · A very ambitious Pinterest board.'}];
const stories=[{name:'Kylie',media:'media/wardrobe.jpg',text:'first look. so proud of you Mia 🤍',sub:'2h',tag:'MIA · CONCEPT PREVIEW'},{name:'Kendall',media:'media/studio.jpg',text:'love seeing my work everywhere. would also love a tag.',sub:'1h',tag:'CAMPAIGN CONCEPT'},{name:'Khloé',media:'media/wardrobe.jpg',text:'27 guests. 0 samples. somehow, a success.',sub:'38m',tag:'BEVERLY HILLS'}];
function instagram(){state.app='instagram';display(`<section class="app"><header class="ig-head"><div class="ig-logo">Instagram</div><div class="tools"><button data-action="ig-activity" aria-label="Activity">${icon('heart')}</button><button data-action="ig-dms" aria-label="Direct messages">${icon('send')}</button></div></header><div class="scroll"><div class="ig-stories"><button class="ig-story" data-action="my-story"><div class="story-ring">${avatar('Mia')}</div>Your story</button>${stories.map((s,i)=>`<button class="ig-story" data-story="${i}"><div class="story-ring">${avatar(s.name)}</div>${s.name.toLowerCase()}</button>`).join('')}</div>${[{name:'Mia',handle:'mia',location:'Beverly Hills',type:'invite',copy:'a first look. apparently I have a brand now. 🤍',likes:'37'},{name:'Kylie',handle:'kylie',location:'MIA · Private concept preview',src:'media/wardrobe.jpg',copy:'concepts, coffee, and a very long family group chat. proud of you Mia 🤍',likes:'148'},{name:'Kendall',handle:'kendall',location:'Los Angeles',src:'media/studio.jpg',copy:'a location mood. please credit your photographer.',likes:'82'}].map((p,i)=>`<article class="ig-post"><div class="ig-post-head">${avatar(p.name,'tiny')}<div class="meta"><b>${p.handle}</b><small>${p.location}</small></div><button data-action="post-options" aria-label="Post options">${icon('ellipsis')}</button></div>${p.type==='invite'?`<button style="display:block;width:100%" data-action="invite-photo">${invite('ig-invite')}</button>`:`<button style="width:100%;display:block" data-photo="${i===1?0:2}"><img class="ig-image" src="${p.src}" alt="Fashion reference image from Mia’s saved inspiration"></button>`}<div class="ig-post-tools"><button data-like="${i}" class="${state.liked.includes(i)?'liked':''}" aria-label="Like this fictional post">${icon('heart',state.liked.includes(i)?'currentColor':'none')}</button><button data-action="post-comments" aria-label="Comments">${icon('chat')}</button><button data-action="share-post" aria-label="Share post">${icon('send')}</button><button data-action="save-post" aria-label="Save post">${icon('bookmark')}</button></div><div class="ig-copy"><b>${Number(p.likes)+(state.liked.includes(i)?1:0)} likes</b><br><b>${p.handle}</b> ${p.copy}<span class="muted">Friday · Fictional story post</span></div></article>`).join('')}</div>${tabs('Feed','ig')}</section>`,true);}
function storyView(i){state.app='story';state.story=i;const s=stories[i];display(`<section class="story-view"><div class="story-progress">${stories.map((_,j)=>`<i class="${j<=i?'on':''}"></i>`).join('')}</div><div class="story-person">${avatar(s.name,'tiny')}<b>${s.name.toLowerCase()}</b><span style="opacity:.5">${s.sub}</span><button data-open="instagram" aria-label="Close Story">${icon('close')}</button></div><button class="story-media" data-action="next-story" aria-label="Next Story"><img src="${s.media}" alt="Fashion mood reference image"></button><div class="story-caption">${s.text}<div style="font-size:10px;margin-top:18px;letter-spacing:2px">${s.tag}</div><div style="font-size:8px;margin-top:16px;font-weight:400">FICTIONAL POST · REFERENCE IMAGERY</div></div><form class="story-reply" id="story-form"><input placeholder="Send message" aria-label="Reply locally to Story"><button type="submit" aria-label="Send local Story reply">${icon('send')}</button></form></section>`);}
function photos(){state.app='photos';display(`<section class="app"><div class="photos-title"><h1>Photos</h1><button data-action="photo-select">Select</button></div><div class="scroll"><div style="padding:3px 17px 15px"><b style="font-size:20px">Brand ideas</b><p style="font-size:11px;color:#999;margin:4px 0">${photoItems.length} items · Shared with the family</p></div><div class="photos-grid">${photoItems.map((p,n)=>{const i=n;return `<button data-photo="${n}" aria-label="Open ${p.title}">${p.type==='invite'?invite():`<img src="${p.src}" style="object-position:${i%2?'left':'right'}" alt="${p.title}">`}</button>`}).join('')}</div><p class="notifications-note">2 reference photos · 1 invitation<br>Not finished products or actual event photographs.</p></div><nav class="bottom-tabs"><button data-open="photos" class="selected">${icon('grid')}Library</button><button data-open="photos">${icon('heart')}For You</button><button data-open="photos">${icon('archive')}Albums</button></nav></section>`,true);}
function photoView(i){state.app='photo';const p=photoItems[i];display(`<section class="photo-view"><div class="toolbar"><button data-open="photos" aria-label="Back to Photos">${icon('back')}</button><div style="text-align:center;font-size:12px">${p.title}<small style="display:block;color:#888;font-size:9px;margin-top:3px">October 14 · Saved image</small></div><button data-action="photo-options">${icon('ellipsis')}</button></div><div class="image-space">${p.type==='invite'?invite():`<img src="${p.src}" alt="${p.title}">`}</div><p class="photo-caption">${p.caption}</p></section>`);}
const notes=[{title:'brand ideas (do not send to Kris)',preview:'elevated basics? maybe? do I need a name first?',text:'brand ideas (do not send to Kris)\n\nelevated basics? maybe?\n\n• clean shapes\n• good fabric\n• nothing that needs explaining\n• is “MIA” a name or just my name?\n\nthings I have:\n✓ a Pinterest board\n✓ relatives with opinions\n\nthings I do not have:\n☐ samples\n☐ a business plan\n☐ any peace\n\nUPDATE: Kris has sent invites. This is no longer a private thought.'},{title:'Kim’s notes on the deck',preview:'“Beauty” is not a strategy. Slide one has to go.',text:'Kim’s notes on the deck\n\n1. What are we actually selling?\n2. Who is the customer? Be specific.\n3. What does it cost to make?\n4. When can you deliver?\n5. Delete “the power of beauty.”\n\n9:00 PM — presentation review\n2:00 AM — finally finished\n\nSaturday: revised business plan.\nApparently the party was not the work.'},{title:'Friday survival list',preview:'charge phone · thank everyone · breathe',text:'Friday survival list\n\n✓ charge phone\n✓ thank Kylie’s team\n✓ credit Kendall\n✓ call the designer back\n✓ breathe\n☐ stop Kris inviting an investor\n\nReminder: today is a concept preview.\nNot a collection launch.\nThere is a difference. Kim has explained it six times.'}];
function notesApp(n=null){state.app='notes';display(`<section class="app notes-app"><div class="toolbar"><button data-action="notes-back">${icon('back')} ${n===null?'Folders':'Notes'}</button><h2>${n===null?'':'All iCloud'}</h2><button data-action="notes-menu">${icon('ellipsis')}</button></div><div class="scroll">${n===null?`<h1>Notes</h1><div class="note-list">${notes.map((n,i)=>`<button class="note-row" data-note="${i}"><strong>${n.title}</strong><small>Wednesday &nbsp; ${n.preview}</small></button>`).join('')}</div><p class="notifications-note">3 notes · On Mia’s iPhone</p>`:`<div class="note-date">October 14 at 9:34 AM</div><article class="note-content"><h1>${notes[n].title}</h1>${esc(notes[n].text.split('\n').slice(1).join('\n'))}</article>`}</div></section>`,true);}
function calendar(day=16){state.app='calendar';display(`<section class="app"><div class="toolbar"><button data-action="calendar-prev">${icon('back')} 2026</button><h2>October</h2><button data-action="calendar-add">${icon('plus')}</button></div><div class="scroll"><div class="calendar-month"><h1>October 2026</h1><div class="weekdays">${['S','M','T','W','T','F','S'].map(d=>`<span>${d}</span>`).join('')}</div><div class="calendar-days">${'<span></span>'.repeat(4)}${Array.from({length:31},(_,i)=>`<button data-day="${i+1}" class="${i+1===day?'active':''} ${[14,16,17].includes(i+1)?'event':''}">${i+1}</button>`).join('')}</div></div><div class="event-list"><div class="event-day">${['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][new Date(2026,9,day).getDay()]}, October ${day}</div>${day===16?'<div class="event-card"><b>MIA — A first look</b><small>6:00 PM – 8:00 PM · Beverly Hills<br>Private concept preview · 27 guests<br>Organized by Kris. Obviously.</small></div>':day===14?'<div class="event-card"><b>Deck review with Kim</b><small>9:00 PM – until Kim says it’s done<br>Bring laptop. And a plan.</small></div>':day===17?'<div class="event-card"><b>Revised business plan → Kim</b><small>10:00 AM · Apparently non-negotiable</small></div><div class="event-card"><b>Investor introduction</b><small>Time TBD · Kris has already called</small></div>':'<p style="font-size:12px;color:#aaa">No events</p>'}</div></div><div class="fiction-tag">FICTIONAL CALENDAR · NO REAL EVENTS</div><nav class="bottom-tabs"><button data-day="14" style="color:#ff3b30">Today</button><button data-day="16" style="color:#ff3b30">Calendars</button><button data-open="mail" style="color:#ff3b30">Inbox</button></nav></section>`,true);}
const mails=[{from:'Kris',subject:'MIA — Friday guest list',preview:'Only 27. A very intimate evening!',body:'Darling,\n\nAttached is the guest list for Friday. Only 27 people. A very intimate evening!\n\nA few friends from fashion, a little press, and someone you should absolutely meet.\n\nDon’t worry about a thing. Just make sure you have something to show them.\n\nLove you!\nKris ❤️'},{from:'Kim',subject:'Re: Deck v12 — final FINAL',preview:'Please stop putting “FINAL” in the filename.',body:'Mia,\n\nThe concept boards look good.\n\nPlease stop putting “FINAL” in the filename until we are actually finished.\n\nBring the revised pricing assumptions tonight. The first slide is still not a business plan.\n\nKim'},{from:'Kylie’s team',subject:'Concept boards — ready for review',preview:'Neutral palette, typography, and your first-look layout.',body:'Hi Mia,\n\nSharing the concept boards for your review.\n\nIncluded:\n— neutral color palette\n— typography direction\n— private preview invitation\n\nThese are concepts, not production-ready assets. Let us know what feels right before we move forward.\n\nThanks!\nBrand team'}];
function mail(n=null){state.app='mail';display(`<section class="app"><div class="toolbar"><button data-action="mail-back">${icon('back')} ${n===null?'Mailboxes':'Inbox'}</button><h2>${n===null?'Inbox':''}</h2><button data-action="mail-options">${icon('ellipsis')}</button></div><div class="scroll">${n===null?`<div style="padding:17px;font-size:30px;font-weight:700">Inbox</div>${mails.map((m,i)=>`<button class="mail-row" data-mail="${i}"><strong>${m.from}</strong>${m.subject}<span>${m.preview}</span></button>`).join('')}`:`<article class="mail-content"><small style="color:#888">From: ${mails[n].from}<br>To: Mia · Wednesday, October 14</small><h2>${mails[n].subject}</h2><div style="white-space:pre-wrap">${mails[n].body}</div></article>`}</div><div class="fiction-tag">FICTIONAL STORY EMAILS · NO REAL EMAIL ACCOUNT</div></section>`,true);}
function settings(wa=false){state.app='settings';display(`<section class="app" style="background:#f2f2f7"><div class="toolbar"><h2>${wa?'WhatsApp Settings':'Settings'}</h2></div><div class="scroll"><div class="panel"><div class="settings-profile">${avatar('Mia')}<span>Mia<small>${wa?'Available':'Mia’s iPhone'}</small></span></div></div><div class="panel"><button class="row" style="width:100%" data-action="wifi"><span>Wi-Fi</span><span class="right">Mia’s Wi-Fi ${icon('chevron')}</span></button><div class="row"><span>Bluetooth</span><span class="right">On</span></div><div class="row"><span>Do Not Disturb</span><button data-action="mute" class="toggle ${state.muted?'':'off'}" aria-label="Toggle Do Not Disturb"></button></div><div class="row"><span>Dim wallpaper</span><button data-action="night" class="toggle ${state.night?'':'off'}" aria-label="Toggle dim wallpaper"></button></div></div><div class="panel"><button class="row" style="width:100%" data-action="about">About this phone <span class="right">${icon('chevron')}</span></button><button class="row" style="width:100%" data-action="download">Download WhatsApp screenshots <span class="right">${icon('download')}</span></button><button class="row" style="width:100%" data-action="lock">Lock Screen <span class="right">${icon('lock')}</span></button></div><p class="notifications-note">A fictional phone, made for a story.<br>All changes stay on this device.</p></div>${wa?tabs('Settings'):''}</section>`,true);}
function contacts(title='Contacts'){state.app='contacts';display(`<section class="app"><div class="toolbar"><h2>${title}</h2><button data-action="contact-info">${icon('plus')}</button></div><div class="scroll contacts-list"><div class="contact-head">${title==='Calls'?'Recent calls':'Contacts'}</div>${names.filter(n=>n!=='Mia').map(n=>`<button class="chat-row" data-call="${n}">${avatar(n)}<div class="rowtext"><div class="rowhead">${n}<span class="call-badge">${icon('phone')}</span></div><p>${title==='Calls'?'Outgoing · Yesterday':'mobile'}</p></div></button>`).join('')}<p class="notifications-note">Simulated calls only.<br>No microphone, camera, or phone connection.</p></div>${title==='Calls'?tabs('Calls'):''}</section>`,true);}
function call(name,video=false){state.app='call';display(`<section class="call-screen">${avatar(name,'big')}<h1>${esc(name)}</h1><div class="call-sub">${video?'Video call':'Calling'}…</div><p class="call-note">${name==='Kris'?'“Darling! Before you hang up, I found another investor.”':'You’ve reached the middle of a family business emergency.'}<br><br><small>Fictional call preview · no connection is made.</small></p><div class="call-buttons"><button data-action="call-mute"><span class="call-circle">${icon('mic')}</span>mute</button><button data-action="call-speaker"><span class="call-circle">${icon('volume')}</span>speaker</button><button data-action="call-video"><span class="call-circle">${icon('video')}</span>video</button></div><button class="hangup" data-action="hangup" aria-label="End simulated call">${icon('phone')}</button></section>`);}
function safari(){state.app='safari';display(`<section class="app"><div class="browser-address">🔒 mia-preview.local</div><div class="scroll"><article class="mini-site"><p style="font-size:9px;letter-spacing:2px">YOU ARE CORDIALLY INVITED</p><h1>MIA</h1><h2>A first look.</h2><p>A private concept preview.<br>Friday · Beverly Hills</p><p>Concept boards. Campaign direction.<br>A family with a very full contact list.</p><button data-action="rsvp">${load('mia-rsvp',false)?'YOU’RE ON THE LIST ✓':'RSVP'}</button><p style="font-size:10px">By invitation only · 27 guests</p><small>Fictional event page.<br>No real event, address, or registration.</small></article></div><div class="toolbar" style="padding-bottom:27px;height:65px"><button data-action="home" aria-label="Home">${icon('back')}</button><button data-action="copy-link" aria-label="Copy link">${icon('share')}</button><button data-open="files" aria-label="Downloads">${icon('download')}</button></div></section>`,true);}
function camera(){state.app='camera';display(`<section class="camera"><div style="display:flex;justify-content:space-between;padding:8px 22px"><button data-action="flashlight" aria-label="Flash">${icon('flash')}</button><button data-action="camera-flip" aria-label="Switch camera">${icon('camera')}</button></div><div class="viewfinder"><img src="media/wardrobe.jpg" alt="Simulated camera view of clothing references"></div><div class="camera-modes"><span>VIDEO</span><b class="selected">PHOTO</b><span>PORTRAIT</span></div><button class="shutter" data-action="shutter" aria-label="Take a simulated photo"></button><small>Fictional camera · uses a saved reference image</small></section>`);}
function messages(){state.app='messages';display(`<section class="app"><div class="toolbar"><h2>Messages</h2><button data-action="sms-compose">${icon('write')}</button></div><div class="scroll"><div style="font-size:30px;font-weight:700;padding:18px">Messages</div><button class="chat-row" data-action="sms-open">${avatar('Mia')}<div class="rowtext"><div class="rowhead">Reminders<time>Yesterday</time></div><p>Your family is on WhatsApp. You have 23 unread.</p></div></button><p class="notifications-note">Family chats live in WhatsApp.</p></div></section>`,true);}
function files(){state.app='files';display(`<section class="app"><div class="toolbar"><h2>On My iPhone</h2><button data-action="download">${icon('download')}</button></div><div class="scroll"><div style="font-size:29px;font-weight:700;padding:17px">Story screenshots</div>${Array.from({length:8},(_,i)=>`<a class="files-row" href="assets/slide-${String(i+1).padStart(2,'0')}.png" download><img src="assets/slide-${String(i+1).padStart(2,'0')}.png" alt="WhatsApp story slide ${i+1}"><span>WhatsApp_${String(i+1).padStart(2,'0')}.png<small>PNG image · Instagram carousel</small></span>${icon('download')}</a>`).join('')}<a class="files-row" href="mia-carousel.zip" download>${icon('archive')}<span>Download all 8 slides<small>ZIP archive</small></span>${icon('download')}</a></div></section>`,true);}
function openApp(app){closeSheet();clearTimers();$('#time').textContent='9:08';({whatsapp:chats,instagram,photos,notes:notesApp,calendar,mail,files,settings,phone:contacts,safari,camera,messages})[app]?.();}
function sheet(title,options=[],body=''){clearTimeout(chapterTimer);$('#overlay').hidden=false;$('#overlay').innerHTML=`<section class="sheet"><div class="sheet-title">${title}</div>${body?`<div class="body">${body}</div>`:''}${options.map(([label,action])=>`<button data-action="${action}">${label}</button>`).join('')}<button data-action="close-sheet">Cancel</button></section>`;}
function closeSheet(){$('#overlay').hidden=true;$('#overlay').innerHTML='';}
function toast(text){$('#notification').hidden=false;$('#notification').innerHTML=`<button class="notification-card" data-action="dismiss-notification">${appIcon('whatsapp')}<div><strong>Mia’s iPhone <small>now</small></strong><p>${esc(text)}</p></div></button>`;clearTimeout(chapterTimer);chapterTimer=setTimeout(()=>$('#notification').hidden=true,3500);}
function about(){sheet('About Mia’s iPhone',[],`<h2>A Family Business</h2><p>A fictional phone you can explore: unlock it, open WhatsApp, read the family chat, check Instagram, browse the camera roll, and find the notes behind the chaos.</p><p><b>All dialogue, DMs, posts, emails, and events are invented fan-made satire.</b> Mia is a fictional younger relative of Kris, not her daughter. This is not affiliated with WhatsApp, Apple, Instagram, or the Kardashian–Jenner family.</p><p>Messages you type, likes, RSVPs, and settings stay in this browser. This phone cannot contact real people, place calls, or publish posts.</p><p>Family portrait: <a target="_blank" rel="noreferrer" href="https://www.soldoutservice.com/kylie-jenner-forbes-la-giovane-influencer-non-e-piu-una-miliardaria/">publicity image via Soldoutservice</a>. Used as contact avatars in this fan story. Fashion reference photos: <a target="_blank" rel="noreferrer" href="https://images.unsplash.com/photo-1445205170230-053b83016050">Unsplash wardrobe</a> · <a target="_blank" rel="noreferrer" href="https://images.unsplash.com/photo-1441986300917-64674bd600d8">store interior reference</a>. Reference imagery is not evidence of an actual brand or event.</p>`);}
function replay(){closeSheet();state.app='chat';state.chat='Family Business';groupChat(0);const box=$('#chat-body');const rows=STORY.scenes.flatMap((s,i)=>s.messages.map((m,j)=>({m,time:s.time.split(' · ')[1],chapter:i,j})));box.innerHTML='<div class="wa-system">Fictional story replay · messages appear in order</div>';state.replay=true;let i=0,prev='';const stop=document.createElement('button');stop.className='replay-stop';stop.dataset.action='stop-replay';stop.textContent='Show full chat';$('#view').append(stop);function next(){if(i>=rows.length){clearInterval(replayTimer);stop.textContent='Replay finished · show full chat';return}const r=rows[i++];if(r.j===0){box.insertAdjacentHTML('beforeend',`<div class="chat-date">${STORY.scenes[r.chapter].time}</div>`);prev=''}box.insertAdjacentHTML('beforeend',msg(r.m,r.time,prev,i));prev=r.m.sender;box.scrollTop=box.scrollHeight;}next();replayTimer=setInterval(next,1300);}
function action(a,e){const map={home,unlock:home,lock,about,'close-sheet':closeSheet,chats,'back-group':()=>groupChat(state.chapter),'notification-open':()=>groupChat(0),'group-info':groupInfo,'chat-menu':()=>sheet('Family Business',[['Group info','group-info'],['Replay the conversation','replay'],['Jump to a moment','scene-picker'],['Jump to the beginning','jump-start'],['Jump to the aftermath','jump-end'],[state.muted?'Unmute notifications':'Mute notifications','mute']]),'wa-menu':()=>sheet('WhatsApp',[['Read the family chat','jump-start'],['Replay the conversation','replay'],['About this story','about']]),replay,'scene-picker':()=>sheet('Jump to a moment',[],`<div>${STORY.scenes.map((s,i)=>`<button data-jump="${i}" style="display:block;width:100%;padding:13px 0;text-align:left;border-bottom:1px solid #ddd">${s.time}<br><b>${s.title}</b></button>`).join('')}</div>`),'stop-replay':()=>groupChat(0),'jump-start':()=>{closeSheet();groupChat(0)},'jump-end':()=>{closeSheet();groupChat(6)},'invite-photo':()=>photoView(1),'video-call':()=>call('Kris',true),'hangup':()=>{if(state.chat==='Family Business')groupChat(state.chapter);else privateChat(state.chat)},'call-mute':()=>{e?.closest('button')?.classList.toggle('selected');toast('Simulated call muted. No microphone is connected.')},'call-speaker':()=>toast('Speaker on · simulated call only'),'call-video':()=>toast('Camera stays off · simulated call only'),mute:()=>{state.muted=!state.muted;closeSheet();if(state.app==='groupinfo')groupInfo();else if(state.app==='settings')settings();else toast(state.muted?'Family Business notifications muted.':'Notifications unmuted.')},night:()=>{state.night=!state.night;save('mia-night',state.night);settings()},'contact-info':()=>sheet(state.chat==='Family Business'?'Contacts':state.chat,[['Open WhatsApp chat','open-contact-chat'],['Simulated call','contact-call']]),'open-contact-chat':()=>{const n=state.chat==='Family Business'?'Kris':state.chat;closeSheet();privateChat(n)},'contact-call':()=>{const n=state.chat==='Family Business'?'Kris':state.chat;closeSheet();call(n)},attach:()=>sheet('Attach',[['Photo Library','attach-photos'],['Document','attach-files']]),'attach-photos':()=>openApp('photos'),'attach-files':()=>openApp('files'),emoji:()=>{const i=$('#message-input');if(i){i.value+=' 😂';i.focus()}},'voice-note':()=>toast('This preview does not record audio. You can type a local message.'),'ig-activity':()=>sheet('Activity',[],`<p><b>Kylie</b> liked your concept preview.</p><p><b>Khloé</b> commented: “No samples. Great lighting.”</p><p><b>Kendall</b> would like a photo credit.</p><p style="font-size:10px;color:#999">Fictional activity within this story.</p>`),'ig-dms':()=>sheet('Messages',[['Kylie — the mood boards are ready','dm-kylie'],['Kendall — you forgot the tag','dm-kendall']]),'dm-kylie':()=>{closeSheet();privateChat('Kylie')},'dm-kendall':()=>{closeSheet();privateChat('Kendall')},'my-story':()=>storyView(0),'next-story':()=>storyView((state.story+1)%3),'post-options':()=>sheet('Post options',[['Save to inspiration','save-post'],['About this story','about']]),'save-post':()=>{closeSheet();toast('Saved to Mia’s inspiration folder.')},'post-comments':()=>sheet('Comments',[],`<p><b>khloe</b> no samples. great lighting. 💀</p><p><b>kendall</b> photo credit??</p><p><b>kylie</b> sorry!!! tagging you now</p><small>Fictional story comments.</small>`),'share-post':()=>sheet('Share',[['Copy this phone’s link','copy-link'],['Open family WhatsApp','jump-start']]),'photo-select':()=>toast('Tap any photo to open it.'),'photo-options':()=>sheet('Saved reference image',[['Back to library','attach-photos'],['About the images','about']]),'notes-back':()=>notesApp(),'notes-menu':()=>sheet('Notes',[['All notes','all-notes']]),'all-notes':()=>{closeSheet();notesApp()},'calendar-prev':()=>calendar(14),'calendar-add':()=>sheet('Story calendar',[],`<p>The preview is on Friday, October 16. Tap October 14, 16, or 17 to read the plans.</p><p>No calendar events are created outside this fictional phone.</p>`),'mail-back':()=>mail(),'mail-options':()=>sheet('Mail',[['Back to inbox','mail-inbox']]),'mail-inbox':()=>{closeSheet();mail()},wifi:()=>toast('Connected to Mia’s Wi-Fi · simulated setting'),weather:()=>sheet('Beverly Hills',[],`<h2>72° · Sunny</h2><p>A fictional Wednesday. High 76° / Low 59°.</p><p>Not a live weather forecast.</p>`),search:()=>sheet('Search this phone',[],`<div class="search-overlay"><input id="app-search" placeholder="Search apps" aria-label="Search apps"><div id="app-search-results" class="search-results">${['whatsapp','instagram','photos','notes','calendar','mail','files','settings'].map(a=>`<button data-open="${a}">${appIcon(a)}${a==='whatsapp'?'WhatsApp':a[0].toUpperCase()+a.slice(1)}</button>`).join('')}</div></div>`),download:()=>openApp('files'),'copy-link':async()=>{closeSheet();if(location.protocol==='file:')return toast('Offline preview. This file does not have a shareable web link.');try{await navigator.clipboard.writeText(location.href.split('#')[0]);toast('Phone link copied.')}catch{toast('Copy the phone link from your browser address bar.')}},rsvp:()=>{save('mia-rsvp',true);safari();toast('Added to the fictional guest list. Nothing was sent.')},shutter:()=>{$('#view').classList.remove('flash');requestAnimationFrame(()=>$('#view').classList.add('flash'));photoItems.push({...photoItems[0],title:'Camera preview capture',caption:'Simulated camera capture from a saved reference image.'});toast('Saved to the fictional camera roll.');},flashlight:()=>{e?.closest('button')?.classList.toggle('selected');toast('Flashlight toggled · visual preview only')},'camera-flip':()=>toast('Camera preview uses a saved reference photo.'),'sms-open':()=>sheet('Reminders',[['Open WhatsApp','jump-start']],'<p>Your family is on WhatsApp. You have 23 unread messages.</p>'),'sms-compose':()=>sheet('Messages',[['Open family WhatsApp','jump-start']])};map[a]?.();}
document.addEventListener('click',e=>{const t=e.target.closest('button,a');if(!t)return;if(t.dataset.open)return openApp(t.dataset.open);if(t.dataset.chat){closeSheet();return t.dataset.chat==='Family Business'?groupChat(0):privateChat(t.dataset.chat)}if(t.dataset.action)return action(t.dataset.action,t);if(t.dataset.filter){state.filter=t.dataset.filter;return chats()}if(t.dataset.watab)return waTab(t.dataset.watab);if(t.dataset.igtab){if(t.dataset.igtab==='Search')return photos();if(t.dataset.igtab==='Create')return camera();if(t.dataset.igtab==='Reels')return storyView(0);return instagram()}if(t.dataset.jump!==undefined){closeSheet();if(state.replay)groupChat(+t.dataset.jump);else jump(+t.dataset.jump);return}if(t.dataset.story!==undefined)return storyView(+t.dataset.story);if(t.dataset.photo!==undefined)return photoView(+t.dataset.photo);if(t.dataset.note!==undefined)return notesApp(+t.dataset.note);if(t.dataset.day)return calendar(+t.dataset.day);if(t.dataset.mail!==undefined)return mail(+t.dataset.mail);if(t.dataset.call){state.chat=t.dataset.call;return call(t.dataset.call)}if(t.dataset.like!==undefined){const i=+t.dataset.like;state.liked=state.liked.includes(i)?state.liked.filter(n=>n!==i):[...state.liked,i];save('mia-liked',state.liked);t.classList.toggle('liked',state.liked.includes(i));t.innerHTML=icon('heart',state.liked.includes(i)?'currentColor':'none');}});
document.addEventListener('submit',e=>{if(e.target.id==='message-form'){e.preventDefault();const input=$('#message-input'),text=input.value.trim();if(!text)return;if(state.replay){clearInterval(replayTimer);state.replay=false;$('.replay-stop')?.remove()}const time='9:08 PM',m={sender:'Mia',text,time};state.drafts[state.chat]??=[];state.drafts[state.chat].push(m);save('mia-local-messages',state.drafts);const box=$('#chat-body');box.insertAdjacentHTML('beforeend',msg(m,time,'Mia'));input.value='';box.scrollTop=box.scrollHeight;}if(e.target.id==='story-form'){e.preventDefault();const input=e.target.querySelector('input');if(input.value.trim()){state.drafts[stories[state.story].name]??=[];state.drafts[stories[state.story].name].push({sender:'Mia',text:input.value.trim(),time:'9:08 PM'});save('mia-local-messages',state.drafts);input.value='';toast('Reply saved to this fictional phone only.')}}});
document.addEventListener('input',e=>{if(e.target.id==='chat-search'){const i=e.target,position=i.selectionStart;chats(i.value);const n=$('#chat-search');n.focus();n.setSelectionRange(position,position)}if(e.target.id==='app-search'){const q=e.target.value.toLowerCase();$$('#app-search-results button').forEach(b=>b.hidden=!b.dataset.open.includes(q))}});
$('#overlay').addEventListener('click',e=>{if(e.target===$('#overlay'))closeSheet()});$('#home').onclick=()=>{closeSheet();home()};$('#about').onclick=about;$('#download-all').onclick=()=>openApp('files');
let touchY=null;$('#phone').addEventListener('touchstart',e=>{touchY=e.touches[0].clientY},{passive:true});$('#phone').addEventListener('touchend',e=>{const end=e.changedTouches[0].clientY;if(state.app==='lock'&&touchY-end>45)home();else if(touchY>$('#phone').getBoundingClientRect().bottom-40&&touchY-end>65){closeSheet();home()}touchY=null},{passive:true});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(!$('#overlay').hidden)closeSheet();else home()}});
lock();
